// Authentic Polytonic Ancient Greek -> Latin-alphabet transliteration for Custom Vocab lists
export function transliterateAncientGreek(text) {
  const s = String(text || '').normalize('NFD');
  const hasRough = /[\u0314]/.test(s);
  const stripped = s.replace(/[\u0300-\u036f]/g, '');
  const map = {
    'α': 'a', 'Α': 'A',
    'β': 'b', 'Β': 'B',
    'γ': 'g', 'Γ': 'G',
    'δ': 'd', 'Δ': 'D',
    'ε': 'e', 'Ε': 'E',
    'ζ': 'z', 'Ζ': 'Z',
    'η': 'ē', 'Η': 'Ē',
    'θ': 'th', 'Θ': 'Th',
    'ι': 'i', 'Ι': 'I',
    'κ': 'k', 'Κ': 'K',
    'λ': 'l', 'Λ': 'L',
    'μ': 'm', 'Μ': 'M',
    'ν': 'n', 'Ν': 'N',
    'ξ': 'x', 'Ξ': 'X',
    'ο': 'o', 'Ο': 'O',
    'π': 'p', 'Π': 'P',
    'ρ': 'r', 'Ρ': 'R',
    'σ': 's', 'ς': 's', 'Σ': 'S',
    'τ': 't', 'Τ': 'T',
    'υ': 'u', 'Υ': 'U',
    'φ': 'ph', 'Φ': 'Ph',
    'χ': 'kh', 'Χ': 'Kh',
    'ψ': 'ps', 'Ψ': 'Ps',
    'ω': 'ō', 'Ω': 'Ō',
  };
  let out = '';
  for (let i = 0; i < stripped.length; i++) {
    const ch = stripped[i];
    const next = stripped[i + 1] || '';
    if ((ch === 'γ' || ch === 'Γ') && ('γκξχΓΚΞΧ'.includes(next))) {
      out += ch === 'Γ' ? 'N' : 'n';
      continue;
    }
    out += map[ch] !== undefined ? map[ch] : ch;
  }
  if (hasRough && /^[aeiouēōAEIOUĒŌrR]/.test(out)) {
    if (out[0] === out[0].toUpperCase() && out[0] !== out[0].toLowerCase()) {
      out = 'H' + out[0].toLowerCase() + out.slice(1);
    } else {
      out = 'h' + out;
    }
  }
  return out.trim();
}

export function parseCustomGreekVocab(rawText) {
  const lines = String(rawText || '').split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const items = [];
  lines.forEach((line, idx) => {
    let parts = null;
    if (line.includes('|')) {
      parts = line.split('|').map(p => p.trim()).filter(Boolean);
    } else if (line.includes('\t')) {
      parts = line.split('\t').map(p => p.trim()).filter(Boolean);
    } else if (/\s+[-–—:]\s+/.test(line)) {
      parts = line.split(/\s+[-–—:]\s+/).map(p => p.trim()).filter(Boolean);
    } else if (line.includes('=')) {
      parts = line.split('=').map(p => p.trim()).filter(Boolean);
    } else if (line.includes(' - ')) {
      parts = line.split(' - ').map(p => p.trim()).filter(Boolean);
    }
    if (!parts || parts.length < 2) return;

    const greek = parts[0];
    let transliteration = '';
    let english = '';
    if (parts.length >= 3) {
      transliteration = parts[1];
      english = parts.slice(2).join(', ');
    } else {
      english = parts[1];
      const baseWord = greek.split(',')[0].trim();
      transliteration = transliterateAncientGreek(baseWord);
    }
    if (!greek || !english) return;
    items.push({
      id: `gv_custom_${idx + 1}`,
      part: 0,
      chapter: 0,
      greek,
      transliteration,
      english,
      partOfSpeech: 'custom',
      grammarNote: 'Custom vocabulary',
    });
  });
  return items;
}
